-- Disposable empty foundation, with fictional identities only. Everything rolls back.
begin;
create function pg_temp.owner_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.owner_denied(statement text,code text,label text) returns void language plpgsql as $$declare actual text;begin begin execute statement;exception when others then get stacked diagnostics actual=returned_sqlstate;end;if actual is distinct from code then raise exception 'FAIL: %, expected %, got %',label,code,actual;end if;raise notice 'PASS: %',label;end$$;
insert into auth.users(id,email,email_confirmed_at) values('bbbbbbbb-bbbb-4bbb-8bbb-000000000001','owner@example.invalid',now()),('bbbbbbbb-bbbb-4bbb-8bbb-000000000002','member@example.invalid',now());
insert into auth.sessions(id,user_id) values('aaaaaaaa-aaaa-4aaa-8aaa-000000000001','bbbbbbbb-bbbb-4bbb-8bbb-000000000001'),('aaaaaaaa-aaaa-4aaa-8aaa-000000000002','bbbbbbbb-bbbb-4bbb-8bbb-000000000002');
update app_private.enrollment_settings set enabled=true,allowed_email_domains=array['example.invalid'],owner_email='owner@example.invalid';
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-000000000002',true),set_config('request.jwt.claims','{"session_id":"aaaaaaaa-aaaa-4aaa-8aaa-000000000002","user_metadata":{"role":"technical_admin","email":"owner@example.invalid"}}',true);
set local role authenticated;
select pg_temp.owner_denied('select owner_email from app_private.enrollment_settings','42501','designated owner address is private');
select pg_temp.owner_denied('select app_private.initialize_application_owner()','42501','browser cannot directly invoke private owner initializer');
select public.complete_self_service_enrollment('Ordinary Example');
select pg_temp.owner_ok(app_private.organization_member_id() is null and app_private.current_member_id() is not null,'ordinary intake is signed in but stays without organizational authority despite forged owner metadata');
select pg_temp.owner_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=0,'ordinary signup cannot see the owner queue');
reset role;
select pg_temp.owner_ok((select count(*)=0 from app_private.role_assignments),'ordinary signup receives zero roles');
select set_config('request.jwt.claim.sub','bbbbbbbb-bbbb-4bbb-8bbb-000000000001',true),set_config('request.jwt.claims','{"session_id":"aaaaaaaa-aaaa-4aaa-8aaa-000000000001"}',true);
set local role authenticated;
select public.complete_self_service_enrollment('Owner Example');
select public.complete_self_service_enrollment('Owner Retry');
select pg_temp.owner_ok(app_private.current_member_id() is not null,'confirmed designated owner can administer while Unassigned');
select pg_temp.owner_ok((public.member_workspace()->'permissions'->>'organization')::boolean,'owner can configure organization');
select pg_temp.owner_ok((public.member_workspace()->'permissions'->>'technical')::boolean,'owner can administer account access');
select pg_temp.owner_ok((public.member_workspace()->'permissions'->>'departmentAdmin')::boolean,'owner can configure departments');
select pg_temp.owner_ok(public.member_workspace()->'self'->>'status'='intake','owner placement remains intake');
select pg_temp.owner_ok(public.member_workspace()->'self'->'unitId'='null'::jsonb,'owner has no fabricated unit');
select pg_temp.owner_ok(jsonb_array_length(public.member_workspace()->'unassignedMembers')=2,'authorized owner sees pending enrollment queue');
reset role;
select pg_temp.owner_ok((select count(*)=3 from app_private.role_assignments),'owner roles granted once on retry');
select pg_temp.owner_ok((select count(*)=1 from app_private.bootstrap_receipts),'owner initialization is one-time');
select pg_temp.owner_ok((select count(*)=1 from app_private.audit_events where operation='application.owner_initialized'),'owner setup audited once');
select pg_temp.owner_ok((select count(*)=0 from public.member_placements) and (select count(*)=0 from public.age_categories) and (select count(*)=0 from public.church_groups) and (select count(*)=0 from public.church_units),'initialization seeds no placement or hierarchy');
update app_private.account_links set technical_enabled=false where auth_user_id='bbbbbbbb-bbbb-4bbb-8bbb-000000000001';
set local role authenticated;
select pg_temp.owner_ok(app_private.current_member_id() is null,'technical suspension immediately removes intake owner authority');
select pg_temp.owner_denied('select public.member_workspace()','42501','suspended owner cannot read workspace');
reset role;update app_private.account_links set technical_enabled=true where auth_user_id='bbbbbbbb-bbbb-4bbb-8bbb-000000000001';
update auth.sessions set not_after=now()-interval '1 second' where user_id='bbbbbbbb-bbbb-4bbb-8bbb-000000000001';
set local role authenticated;
select pg_temp.owner_ok(app_private.current_member_id() is null,'expired session removes owner authority');
reset role;
rollback;
